  "robowar-3lbs": {
    "title": "ROBOWAR 3 LBS",
    "subtitle": "OFFICIAL 3LBS BEETLEWEIGHT COMBAT ROBOTICS RULEBOOK",
    "html": "\n    <div class=\"rb-section\">\n      <div class=\"rb-section-header\">\n        <span class=\"rb-section-tag\">OVERVIEW</span>\n        <h4 class=\"rb-section-title\">ABOUT THE EVENT (3 LBS CATEGORY)</h4>\n      </div>\n      <p class=\"rb-paragraph\">The <strong>RoboWar 3lbs</strong> category features high-speed, compact combat robotics where bots weighing up to 1.5 kg battle in a single-elimination tournament. Test mechanical integrity, weapon RPM, armor resilience, and tactical driving under 3-minute combat rounds.</p>\n    </div>\n\n    <div class=\"rb-section\">\n      <div class=\"rb-section-header\">\n        <span class=\"rb-section-tag\">TEAMS</span>\n        <h4 class=\"rb-section-title\">TEAM SPECIFICATIONS & ROSTERS</h4>\n      </div>\n      <ul class=\"rb-list\">\n        <li><span><strong>Team Size:</strong> Minimum of 1 and maximum of 4 participants per team.</span></li>\n        <li><span><strong>Inter-College Eligibility:</strong> Students from different educational institutes are permitted to form unified squads.</span></li>\n      </ul>\n    </div>\n\n    <div class=\"rb-section\">\n      <div class=\"rb-section-header\">\n        <span class=\"rb-section-tag\">SPECS</span>\n        <h4 class=\"rb-section-title\">BOT SPECIFICATIONS (UP TO 1.5 KG)</h4>\n      </div>\n      <div class=\"rb-specs-grid\">\n        <div class=\"rb-spec-item\"><span class=\"rb-spec-key\">MAX WEIGHT</span><span class=\"rb-spec-val\">3 LBS (UP TO 1.5 KG MAX)</span></div>\n        <div class=\"rb-spec-item\"><span class=\"rb-spec-key\">WEIGHT TOLERANCE</span><span class=\"rb-spec-val\">0% TOLERANCE (NO OVERWEIGHT)</span></div>\n        <div class=\"rb-spec-item\"><span class=\"rb-spec-key\">ACTIVE WEAPON</span><span class=\"rb-spec-val\">MANDATORY ACTIVE WEAPON</span></div>\n        <div class=\"rb-spec-item\"><span class=\"rb-spec-key\">CONNECTIVITY</span><span class=\"rb-spec-val\">TRULY WIRELESS ONLY</span></div>\n        <div class=\"rb-spec-item\"><span class=\"rb-spec-key\">KILL SWITCH</span><span class=\"rb-spec-val\">MANDATORY FAILSAFE SWITCH</span></div>\n        <div class=\"rb-spec-item\"><span class=\"rb-spec-key\">POWER SUPPLY</span><span class=\"rb-spec-val\">DC BATTERIES ONLY (NO AC)</span></div>\n      </div>\n    </div>\n\n    <div class=\"rb-section\">\n      <div class=\"rb-section-header\">\n        <span class=\"rb-section-tag\">RULES</span>\n        <h4 class=\"rb-section-title\">MATCH RULES & WIN CONDITIONS</h4>\n      </div>\n      <ol class=\"rb-numbered-list\">\n        <li><span><strong>Knockout Elimination:</strong> Matches played on a single-elimination knockout bracket with 3-minute rounds.</span></li>\n        <li><span><strong>Active Weapon Requirement:</strong> Bots must incorporate a functional, powered active weapon. Passive pushers/wedges are prohibited.</span></li>\n        <li><span><strong>10-Second Inactivity:</strong> Inability to displace or demonstrate controlled translational movement for more than 10 seconds results in round loss.</span></li>\n        <li><span><strong>Safety Inspection:</strong> Safety inspection must be passed before fighting; hazardous bots will be rejected immediately.</span></li>\n        <li><span><strong>Discipline & Zero Tolerance:</strong> 2–3 arena calls before forfeiture. Zero tolerance for physical violence, verbal abuse, or harassment.</span></li>\n      </ol>\n    </div>\n\n    <div class=\"rb-section\">\n      <div class=\"rb-section-header\">\n        <span class=\"rb-section-tag\">AWARDS</span>\n        <h4 class=\"rb-section-title\">CERTIFICATION & AWARDS</h4>\n      </div>\n      <ul class=\"rb-list\">\n        <li><span><strong>Certificates of Excellence:</strong> Awarded to the top 2 overall winners.</span></li>\n        <li><span><strong>Certificates of Participation:</strong> Given to all participating teams who comply with tournament rules.</span></li>\n      </ul>\n      <div class=\"rb-motto-box\">\n        <span class=\"rb-motto-text\">COMPACT POWER. HIGH SPEED. CLASH FOR GLORY.</span>\n      </div>\n    </div>\n    "
  },
